using System;using System.IO;using System.Linq;using System.Reflection;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
namespace Underwater.Editor {
[InitializeOnLoad] public static class DolphinLiveSyncCheck {
 const string Key="Underwater.DolphinLiveSync",Output="Renders/DolphinFins/Live/";static DolphinSwimController[] fish;static Vector3[][] first;static Vector3[] previous;static float[] distance,deformation,maxBlink,mouthMin,mouthMax;static float pausedClock;static int stage;static double began,stageStart;static bool failed;static Camera camera;static int frames;static double nextFrame;static int quietSamples,poweredSamples;static Transform[] leftFins,rightFins;static Quaternion[] leftStart,rightStart;static float[] leftMotion,rightMotion;static Vector3 finAnchor;
 static DolphinLiveSyncCheck(){EditorApplication.update+=Tick;EditorApplication.playModeStateChanged+=Changed;}
 public static void Run(){SessionState.SetBool(Key,true);EditorSceneManager.OpenScene("Assets/Scenes/Underwater_Realistic.unity");EditorApplication.EnterPlaymode();}
 static void Changed(PlayModeStateChange mode){if(mode==PlayModeStateChange.EnteredEditMode&&SessionState.GetBool(Key,false)){SessionState.SetBool(Key,false);EditorApplication.Exit(failed?1:0);}}
 static Vector3[] Points(DolphinSwimController d){var p=OctopusRepairValidation.Points(d.skin);for(int i=0;i<p.Length;i++)p[i]=d.transform.InverseTransformPoint(p[i]);return p;}
 static void Tick(){if(!SessionState.GetBool(Key,false)||!EditorApplication.isPlaying||Time.timeSinceLevelLoad<2)return;
 try{
 if(fish==null){Directory.CreateDirectory(Output);typeof(Diver).GetField("menu",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(Diver.Instance,false);fish=UnityEngine.Object.FindObjectsByType<DolphinSwimController>(FindObjectsSortMode.None).OrderBy(d=>d.podIndex).ToArray();if(fish.Length!=3)throw new Exception("Missing dolphin controllers");leftFins=fish.Select(d=>d.animationPlayer.GetComponentsInChildren<Transform>().Single(t=>t.name=="FLIPPER_L02")).ToArray();rightFins=fish.Select(d=>d.animationPlayer.GetComponentsInChildren<Transform>().Single(t=>t.name=="FLIPPER_R02")).ToArray();leftStart=leftFins.Select(t=>t.localRotation).ToArray();rightStart=rightFins.Select(t=>t.localRotation).ToArray();leftMotion=new float[3];rightMotion=new float[3];var fin=fish[0].animationPlayer.GetComponentsInChildren<Transform>().Single(t=>t.name=="FLIPPER_L01");finAnchor=fish[0].transform.InverseTransformPoint(fin.position);previous=fish.Select(d=>d.transform.position).ToArray();first=fish.Select(Points).ToArray();distance=new float[3];deformation=new float[3];maxBlink=new float[3];mouthMin=Enumerable.Repeat(float.MaxValue,3).ToArray();mouthMax=Enumerable.Repeat(float.MinValue,3).ToArray();began=stageStart=EditorApplication.timeSinceStartup;camera=new GameObject("Temporary dolphin live camera").AddComponent<Camera>();camera.CopyFrom(Camera.main);camera.enabled=true;camera.depth=Camera.main.depth+1;camera.fieldOfView=46;var anchor=fish[0].GetComponent<WreckCreature>().habitatCenter;camera.transform.position=anchor+new Vector3(17,10,10);camera.transform.LookAt(anchor);return;}
 if(EditorApplication.timeSinceStartup-began>45)throw new Exception("Dolphin live test timeout");if(stage==1){if(EditorApplication.timeSinceStartup-stageStart<.6)return;if(Mathf.Abs(fish[0].Clock-pausedClock)>.001f)throw new Exception("Dolphin ignored menu pause");var report=new System.Text.StringBuilder();for(int i=0;i<3;i++){if(leftMotion[i]<2||rightMotion[i]<2)throw new Exception("Live fin movement missing: "+i);report.AppendLine("Actual Update fin angles: left="+leftMotion[i]+" right="+rightMotion[i]+" deg.");if(distance[i]<.5f||deformation[i]<.08f||maxBlink[i]<.7f||mouthMax[i]-mouthMin[i]<.2f)throw new Exception("Runtime dolphin animation missing: "+i+" distance="+distance[i]+" deformation="+deformation[i]+" blink="+maxBlink[i]+" mouth="+(mouthMax[i]-mouthMin[i]));report.AppendLine(fish[i].name+" actual Update travel="+distance[i]+" m; local skin deformation="+deformation[i]+" m; peak blink="+maxBlink[i]+"; mouth angle range="+(mouthMax[i]-mouthMin[i])+" deg; stroke rate="+fish[i].StrokeRate);}report.AppendLine("Moving with quiet tail frames="+quietSamples+"; powered frames="+poweredSamples+".");File.WriteAllText(Output+"FrameCount.txt",frames.ToString());report.AppendLine("Runtime menu pause passed. Legacy playback disabled; one movement/pose owner per dolphin.");File.WriteAllText(Output+"Validation.txt",report.ToString());Debug.Log("DOLPHIN_LIVE_SYNC_VALIDATED\n"+report);EditorApplication.ExitPlaymode();return;}
 for(int i=0;i<3;i++){leftMotion[i]=Mathf.Max(leftMotion[i],Quaternion.Angle(leftStart[i],leftFins[i].localRotation));rightMotion[i]=Mathf.Max(rightMotion[i],Quaternion.Angle(rightStart[i],rightFins[i].localRotation));distance[i]+=(fish[i].transform.position-previous[i]).magnitude;previous[i]=fish[i].transform.position;maxBlink[i]=Mathf.Max(maxBlink[i],fish[i].Blink);mouthMin[i]=Mathf.Min(mouthMin[i],fish[i].MouthAngle);mouthMax[i]=Mathf.Max(mouthMax[i],fish[i].MouthAngle);if(!fish[i].GetComponent<ReefSphereBody>().Clear(fish[i].transform.position))throw new Exception("Live dolphin collision");}
 if(EditorApplication.timeSinceStartup>=nextFrame){nextFrame=EditorApplication.timeSinceStartup+.12;for(int i=0;i<3;i++){var p=Points(fish[i]);for(int j=0;j<p.Length;j++)deformation[i]=Mathf.Max(deformation[i],(p[j]-first[i][j]).magnitude);}var d=fish[0];var anchor=d.transform.TransformPoint(finAnchor);camera.transform.position=anchor+d.transform.right*1.45f-d.transform.forward*.4f-Vector3.up*.1f;camera.transform.LookAt(anchor);if(d.ActualSpeed>.3f&&d.Effort<.15f)quietSamples++;if(d.Effort>.5f)poweredSamples++;ReefCorrectionAudit.Capture(camera,Output+"Body"+frames.ToString("D3")+".png");frames++;}
 if(EditorApplication.timeSinceStartup-stageStart>20){pausedClock=fish[0].Clock;typeof(Diver).GetField("menu",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(Diver.Instance,true);stage=1;stageStart=EditorApplication.timeSinceStartup;}
 }catch(Exception e){failed=true;Debug.LogException(e);EditorApplication.ExitPlaymode();}}
}
}


